      "explanation": "IT 治理管理层次大致可分为三层：最高管理层、执行管理层、业务与服务执行层。 最高管理层的主要职责包括：证实IT 战略与业务战略是否一致；证实通过明确的期望和衡量手段交付IT 价 值；指导IT 战略、平衡支持组织当前和未来发展的投资；指导信息和数据资源的分配。 执行管理层的主要职责包括：制定IT 的目标；分析新技术的机遇和风险；建设关键过程与核心竞争力；分配 责任、定义规程、衡量业绩；管理风险和获得可靠保证等。 业务及服务执行层的主要职责包括：信息和数据服务的提供和支持；IT 基础设施的建设和维护；IT 需求的提 出和响应。"
