      "explanation": "《蜗牛软考202405高项冲刺精华》第3章- 【考点6】审计流程★★★★ 审计流程一般分为审计准备、审计实施、审计终结及后续审计四个阶段阿牛。口诀：准时终序】 审计准备阶段 准备阶段工作一般包括：①明确审计目的及任务；②组建审计项目组；③搜集相关信息； ④编制审计计划等。 审计实施阶段 实施阶段主要完成工作包括：①深入调查并调整审计计划；②了解并初步评估IT内部控制； ③进行符合性测试；④进行实质性测试等。 审计终结阶段 终结阶段的工作一般包括：①整理与复核审计工作底稿；②整理审计证据；③评价相关IT 控制目标的实现；④判断并报告审计发现；⑤沟通审计结果；⑥出具审计报告；⑦归档管 理等。 后续审计阶段 后续审计是在审计报告发出后的一定时间内，审计人员为检查被审计单位对审计问题和建 议是否己经采取了适当的纠正措施，并取得预期效果的跟踪审计。后续审计并不是一次新 的审计，而是前一次审计的有机组成部分。实施后续审计，可不必遵守审计流程的每一过 程和要求，但必须依法依规进行检查、调查，收集审计证据，写出后续审计报告。"
