      "id": "N03-034",
      "stem": "审计抽样方法分为统计抽样和非统计抽样，以下属于非统计抽样的是()。",
      "options": {
        "A": "属性抽样",
        "B": "变量抽样",
        "C": "判断抽样",
        "D": "随机抽样"
      },
      "answer": "C",
      "explanation": "审计抽样方法 说明 统计抽样 采用客观的方法来确定样本量和样本抽取标准。统计抽样采用概率学原理，涉及计算样本量、 抽取样本。 评价样本结果并做出推断。利用统计抽样，审计人员可以量化描述样本与总体的接近程度(评 价抽样精度)以及用百分比表示的样本能够代表总体的概念(可靠性或置信水平)。有效的 统计抽样结果是量化的。 常用的统计抽样方法有：①属性抽样。固定样本量属性抽样或频率估计抽样一用于估计总体 中某种特性(属性)的发生比率(百分率)的抽样方法，属性抽样回答“有多少?”的问题。 可被测试的属性的一个例子是计算机访问申请表上的批准签字。②变量抽样。变量抽样也称 为金额估计抽样或平均值估计抽样，是一种由样本估计总体的货币金额或其他度量单位(如 重量)的抽样技术。变量抽样的一个例子是检查组织重要交易的余额表及对生成余额表的程 序实施的应用系统审计。 非统计抽样 常指判断抽样一采用审计人员判断来确定抽样方法、样本量及抽样标准。抽样结果是基于审 计人员对抽样事项或交易的重要性及风险的主观判断。"
