      "options": {
        "A": "①②③⑤④",
        "B": "③①②④⑤",
        "C": "①④②③⑤",
        "D": "③①④②⑤"
      },
      "answer": "B",
      "explanation": "《蜗牛软考综合一本通》 -5.2.2 数据标准化★★★★★ 表5-10数据元制定的基本过程 步骤 说 明 描述 用于描述数据的内容、覆盖范围、质量、管理方式、数据的所有者、数据的提 供方式等信息，是数据与用户之间的桥梁。 界定业务范围 通过对业务范围的明确界定，确定所要研究的数据元的范围。 开展业务流程分析与信息 建模 数据虽然是任何业务的核心所在，但并不能脱离业务流程而单独存在，它总是 服务于业务流程，因此通过对业务流程的透彻分析，并建立清晰的数据模型， 可以理清整个业务流程中涉及的所有数据元。 借助于信息模型，提取数据 元，并按照一定的规则规范 其属性 GB/T18391《信息技术数据元的规范与标准化》清晰地给出了如何对数据元 进行描述的方法，以及如何赋予数据元属性的值。比如如何描写数据元的定义， 如何对数据元进行命名，如何区分数据元的数据类型等。 对于代码型的数据元，编制 其值域，即代码表 代码表的编写可以按照GB/T7026《标准化工作导则信息分类编码标准的编 写规定》进行。 与现有的国家标准或行业 标准进行协调 这一步是非常重要的工作，编制数据元标准首先要与相应的国家标准保持一 致。首先，如果能直接使用现有的国家标准，则可直接使用，或在国家标准的 基础上进行扩展；其次要与相关的行业标准保持一致；然后还必须考虑与本行 业或领域内已有标准保持最大兼容性，因此要全面考虑协调性和配套性。 发布实施数据元标准并建 立相应的动态维护管理机 制 数据元的标准化工作是一项长期持续的工作，任何行业或领域的数据元标准化 工作都不可能在短时间内全部完成，它不仅需要各级业务部门的长期工作和共 同努力，还需要根据业务需求的不断变化对其进行修改、补充和完善。因此， 需要一种动态维护管理的机制来保障数据元标准化的持续进行。通过建立数据 元注册系统，对数据元进行动态维护管理，一方面可以方便用户定位、查找 和交换数据元规范，另一方面可以有效保证数据元标准的时效性"
